body:
> Further more, racing coroutines isn't natively supported by gdscript, and the implementation isn't trivial.

I'm not sure what you mean by racing coroutines.

But as long as you don't want to support custom callables, you can totally write a util to resume when the object gets freed. Here's my quick attempt at doing so, seems to solve your MRP at least:

<details>
<summary>Code</summary>

```gdscript
## Use [code]or_canceled[/code] instead.
class _OrCanceled extends RefCounted:
	class _LifetimeMonitor:
		var owner: _OrCanceled
		func _init(p_owner: _OrCanceled) -> void:
			owner = p_owner
		func _notification(what) -> void:
			if what == NOTIFICATION_PREDELETE:
				owner._is_done = true
				owner._signal_done.emit()

	var _is_done
	signal _signal_done

	var _function: Callable
	func _init(function: Callable, args: Array) -> void:
		_function = function
		var monitor = _LifetimeMonitor.new(self)
		_monitor = weakref(monitor)
		if function.get_object().has_meta(&"_htk_lifetime_monitors"):
			function.get_object().get_meta(&"_htk_lifetime_monitors").append(monitor)
		else:
			function.get_object().set_meta(&"_htk_lifetime_monitors", [monitor])
		monitor = null
		_exec(function, args)

	func _exec(function: Callable, args: Array) -> void:
		await function.callv(args)
		_is_done = true
		_signal_done.emit()

	var _monitor: WeakRef

	func _do_await():
		if _is_done:
			return
		await _signal_done
		var monitor = _monitor.get_ref()
		if monitor:
			if len(_function.get_object().get_meta(&"_htk_lifetime_monitors")) == 1:
				_function.get_object().remove_meta(&"_htk_lifetime_monitors")
			else:
				_function.get_object().get_meta(&"_htk_lifetime_monitors").erase(monitor)


## A coroutine that launches [param function] and returns when it is done.
##
## In contrast to regularily awaiting [param function] the caller will also be resumed if
## [param function] is canceled. You need to ensure you are prepared to handle
## invalid state resulting from that.
## Does only support regular object callables. Does not account for cancellation
## by other causes than the object of the callable being freed.
func or_canceled(function: Callable, ...args: Array) -> void:
	if not function.is_standard() or not function.get_object():
		push_error("Received unsupported callable")
		return
	var ref = _OrCanceled.new(function, args)
	await ref._do_await()
```
